"""Agente: sin tope de posiciones, historial con nombre del activo y términos de la vigilancia

Ejecutar desde la raíz del proyecto:   python instalar_agente_ajustes.py
Idempotente, sin .bak. Cada archivo debe estar en alguna de las versiones conocidas (la actual de Cristian, o la de
una etapa intermedia del trabajo de Emilio); si alguno tiene cambios distintos, NO se instala nada y se indica cuál.
"""
import base64, hashlib, io, json, os, sys, zipfile

# Hashes de los estados de partida aceptados por archivo (None = el archivo no existía) y archivos que se eliminan.
ACEPTADAS = json.loads("{\"aplicacion_principal/dialogos.py\": [\"0e9e2fdcd513a54d6203f67ea1f9d815d0069ff9eda59d0c6fac93e3b6676c39\"], \"componentes_plataforma/agente_paneles/formato.py\": [\"260455e2acbe3c1724ed4ee2576405f93a34efdd467723eec025c3398a913914\"], \"componentes_plataforma/agente_paneles/vigilancias.py\": [\"cadb9c3793089313a582b13ccecb1b883d21e4ff3719ae0b333bf4321260930c\"], \"componentes_plataforma/vigilancia_terminos/__init__.py\": [null], \"componentes_plataforma/vigilancia_terminos/dialogo.py\": [null], \"componentes_plataforma/vigilancia_terminos/estado.py\": [null], \"componentes_plataforma/vigilancia_terminos/estilos.css\": [null], \"componentes_plataforma/vigilancia_terminos/registro.py\": [null], \"componentes_plataforma/vigilancia_terminos/terminos.html\": [null], \"herramientas_agente/ordenes_herramientas/esquemas.json\": [\"183415b18852bf2be628c4d497fb594c8b5a4fbceea1d737d77c1260d7a745e5\"], \"nucleo_agente/ordenes/envio.py\": [\"c15708d1853526c238091456941a161c90f7a5f2030c7127fad5e8098ba05d39\"], \"nucleo_agente/ordenes/limites.py\": [\"5d2229bdaccf847274227011ecaee39bb7443a01f7434a6ae702c58132d5962d\"], \"nucleo_agente/ordenes/mt5_utiles.py\": [\"e58f447187bb24c625d8e65d9ed1cdf2dc6f19045de3ce8aa42937989aa96698\"]}")
ARCHIVOS = ["aplicacion_principal/dialogos.py", "componentes_plataforma/agente_paneles/formato.py", "componentes_plataforma/agente_paneles/vigilancias.py", "componentes_plataforma/vigilancia_terminos/__init__.py", "componentes_plataforma/vigilancia_terminos/dialogo.py", "componentes_plataforma/vigilancia_terminos/estado.py", "componentes_plataforma/vigilancia_terminos/estilos.css", "componentes_plataforma/vigilancia_terminos/registro.py", "componentes_plataforma/vigilancia_terminos/terminos.html", "herramientas_agente/ordenes_herramientas/esquemas.json", "nucleo_agente/ordenes/envio.py", "nucleo_agente/ordenes/limites.py", "nucleo_agente/ordenes/mt5_utiles.py"]
BORRAR = []
ZIP_B64 = ""


def norm(b):
    return b.replace(b"\r\n", b"\n")


def sha(f):
    """Hash del archivo (sin distinguir saltos de línea de Windows) o None si no existe."""
    return hashlib.sha256(norm(open(f, "rb").read())).hexdigest() if os.path.exists(f) else None


def main():
    z = zipfile.ZipFile(io.BytesIO(base64.b64decode(ZIP_B64)))
    nuevos = {f: norm(z.read(f)) for f in ARCHIVOS}
    destino = {f: hashlib.sha256(nuevos[f]).hexdigest() for f in ARCHIVOS}
    pendientes = [f for f in ARCHIVOS if sha(f) != destino[f]]
    a_borrar = [f for f in BORRAR if os.path.exists(f)]
    if not pendientes and not a_borrar:
        print("Ya estaba instalado: no hay nada que hacer.")
        return
    problemas = [f + (" ya existe con otro contenido" if sha(f) else " falta") + " o difiere de las versiones conocidas (¿cambios sin subir?)"
                 for f in pendientes if sha(f) not in ACEPTADAS[f]]
    if problemas:
        print("No se instaló nada:")
        for p in problemas:
            print("  -", p)
        sys.exit(1)
    for f in pendientes:
        datos = nuevos[f]
        os.makedirs(os.path.dirname(f) or ".", exist_ok=True)
        if os.path.exists(f) and b"\r\n" in open(f, "rb").read():
            datos = datos.replace(b"\n", b"\r\n")
        with open(f, "wb") as fh:
            fh.write(datos)
    for f in a_borrar:
        os.remove(f)
    print("Listo: %d archivos actualizados, %d eliminados." % (len(pendientes), len(a_borrar)))


if __name__ == "__main__":
    main()
